/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Telegram bridge: long-poll getUpdates; route owner messages through the
   chat gateway (session tg-<chatId>), send replies back. Offset persists in
   the telegram_state data table. Owner-only: strangers are ignored. */
const AUTH = 'Bea' + 'rer ' + ($env.CHAT_API_KEY || '');
const TOKEN = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const OWNER = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!TOKEN || !OWNER) return [{ json: { ok: false, error: 'telegram env missing (token / chat_id)' } }];

const N8N = 'http://localhost:5678/api/v1';
const apiJson = (method, path, qs, body) => this.helpers.httpRequest({ method, url: N8N + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body });
const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + TOKEN + '/' + method, headers: { 'Content-Type': 'application/json' }, body, timeout: 60000 });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const tables = (await apiJson('GET', '/data-tables', { limit: 100 })).data || [];
const stateId = (tables.find((t) => t.name === 'telegram_state') || {}).id;
const msgTableId = (tables.find((t) => t.name === 'chat_messages') || {}).id;

let offset = 0;
if (stateId) {
  const rows = (await apiJson('GET', '/data-tables/' + stateId + '/rows', { limit: 10 })).data || [];
  const r = rows.find((x) => x.key === 'last_update_id');
  if (r) offset = Number(r.value) || 0;
}
const saveState = async (key, v) => {
  const filter = encodeURIComponent(JSON.stringify({ type: 'and', filters: [{ columnName: 'key', condition: 'eq', value: key }] }));
  await this.helpers.httpRequest({ method: 'DELETE', url: N8N + '/data-tables/' + stateId + '/rows/delete?filter=' + filter, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, timeout: 10000 }).catch(() => {});
  await apiJson('POST', '/data-tables/' + stateId + '/rows', null, { data: [{ key, value: String(v) }] }).catch(() => {});
};
let lastSaved = offset;
const saveOffset = async (v) => { if (!stateId || v === lastSaved) return; await saveState("last_update_id", v); lastSaved = v; };
// single-run lock: skip if another run started <75s ago (prevents overlapping pollers)
let lockTs = 0;
if (stateId) {
  const lockRows = (await apiJson('GET', '/data-tables/' + stateId + '/rows', { limit: 20 })).data || [];
  const lr = lockRows.find((x) => x.key === 'lock_ts');
  if (lr) lockTs = Number(lr.value) || 0;
}
if (Date.now() - lockTs < 75000) {
  return [{ json: { ok: true, skipped: 'busy', lock_age_ms: Date.now() - lockTs } }];
}
if (stateId) await saveState('lock_ts', String(Date.now()));

const started = Date.now();
let processed = 0;
let sent = 0;
let sendFailed = 0;
const notes = [];
const pendingMinutes = {};

  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const mdToHtml = (t) => {
    let s = esc(t);
    s = s.replace(/```([\s\S]*?)```/g, (_, c) => '<pre>' + c.replace(/^\n+|\n+$/g, '') + '</pre>');
    s = s.replace(/`([^`\n]+)`/g, '<code>$1</code>');
    s = s.replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>');
    s = s.replace(/\*([^*\n]+)\*/g, '<i>$1</i>');
    s = s.replace(/\[([^\]\n]+)\]\((https?:\/\/[^)\s]+)\)/g, '<a href="$2">$1</a>');
    return s;
  };
  const chunkSmart = (t, cap) => {
    const parts = [];
    let rest = String(t || '');
    while (rest.length > cap) {
      let cut = rest.lastIndexOf('\n\n', cap);
      if (cut < cap * 0.4) cut = rest.lastIndexOf('\n', cap);
      if (cut < cap * 0.4) cut = cap;
      parts.push(rest.slice(0, cut));
      rest = rest.slice(cut).replace(/^\n+/, '');
    }
    if (rest.length) parts.push(rest);
    return parts;
  };
  const sendText = async (chatId, text) => {
    const parts = chunkSmart(String(text || ''), 3000);
    for (let i = 0; i < parts.length && i < 8; i++) {
      const html = mdToHtml(parts[i]);
      const r = await tg('sendMessage', { chat_id: chatId, text: html, parse_mode: 'HTML', disable_web_page_preview: true }).catch(() => null);
      if (r && r.ok) sent += 1;
      else {
        const r2 = await tg('sendMessage', { chat_id: chatId, text: parts[i] }).catch(() => null);
        if (r2 && r2.ok) sent += 1; else sendFailed += 1;
      }
      if (parts.length > 1) await sleep(400);
    }
  };

while (Date.now() - started < 50000) {
  const up = await tg('getUpdates', { offset: offset + 1, timeout: 20, allowed_updates: ['message'] }).catch(() => null);
  if (!up || !up.ok) break;
  const list = up.result || [];
  if (!list.length) continue;
  for (const u of list) {
    offset = Math.max(offset, Number(u.update_id) || 0);
    const msg = u.message || {};
    const chatId = String((msg.chat || {}).id || '');
    let text = String(msg.text || '').trim();
    if (chatId !== OWNER) { notes.push('ignored:' + chatId); continue; }
    let viaVoice = false;
    let viaImage = false;
    let imgDataUri = '';
    if (!text && msg.voice && msg.voice.file_id) {
      try {
        await tg('sendChatAction', { chat_id: chatId, action: 'typing' }).catch(() => {});
        const tr = await this.helpers.httpRequest({ method: 'POST', url: 'http://stream-bridge:3211/voice/transcribe', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { file_id: msg.voice.file_id }, timeout: 120000 });
        text = String((tr && tr.text) || '').trim();
        viaVoice = true;
        if (!text) { await sendText(chatId, '这条语音我没听清内容，再说一遍或发文字？'); notes.push('voice-empty'); continue; }
        notes.push('voice:' + text.slice(0, 16));
      } catch (eVo) {
        await sendText(chatId, '语音识别没成功，再试一次或发文字？');
        notes.push('voice-fail');
        continue;
      }
    }
    if (!text && ((msg.photo && msg.photo.length) || (msg.document && /^image\//.test(String(msg.document.mime_type || ''))))) {
      const fileId = msg.photo && msg.photo.length ? msg.photo[msg.photo.length - 1].file_id : msg.document.file_id;
      try {
        await tg('sendChatAction', { chat_id: chatId, action: 'typing' }).catch(() => {});
        const im = await this.helpers.httpRequest({ method: 'POST', url: 'http://stream-bridge:3211/image/fetch', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { file_id: fileId }, timeout: 90000 });
        if (im && im.ok && im.data_uri) {
          imgDataUri = String(im.data_uri);
          text = String(msg.caption || '').trim() || '看看这张图，简短说说内容。';
          viaImage = true;
          notes.push('image:' + (im.bytes || 0) + 'B');
        } else {
          await sendText(chatId, '图片没取到，再发一次试试？');
          notes.push('image-fail');
          continue;
        }
      } catch (eImg) {
        await sendText(chatId, '图片处理出错了，再发一次试试？');
        notes.push('image-fail');
        continue;
      }
    }
    if (!text) continue;
    if (pendingMinutes[chatId] && (Date.now() - pendingMinutes[chatId]) < 30 * 60000 && text.charAt(0) !== '/') {
      delete pendingMinutes[chatId];
      try {
        const mr2 = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/admin/docforge', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { action: 'create', kind: 'minutes', text: text.slice(0, 6000) }, timeout: 120000 });
        if (mr2 && mr2.ok) {
          const base2 = String($env.CONSOLE_URL || $env.APP_URL || 'http://localhost:3000').replace(/\/$/, '');
          await sendText(chatId, '纪要已生成：' + mr2.title + String.fromCharCode(10) + '抽出 ' + (mr2.actions || 0) + ' 条行动项' + String.fromCharCode(10) + base2 + '/api/n8n/docs/' + mr2.id);
        } else await sendText(chatId, '纪要生成失败，稍后再试。');
      } catch (eMin2) { await sendText(chatId, '纪要生成失败，稍后再试。'); }
      processed += 1; notes.push('minutes-body'); continue;
    }
    if (text === '/start' || text === '/help') {
      await sendText(chatId, '你好，我是你的个人 AI 平台。直接说事即可，例如：平台现在怎么样？ / 1 分钟后提醒我喝水 / 帮我跑一份今天的晨报 / 把这句存进知识库：……  ；/reset 清空本会话记忆；/tools 查看自建流程工具；/people 人员目录；/todo @张三 周五前交周报（派发）；/ack 14 标记对方已接（停止催办）；/done 14 完成待办（含别人交回来的）；/mine 只看我自己的待办；/waiting 我派出去的事卡在谁那；/docs 最近文档；/share 6 把文档推给自己（/share 6 @张伟 定向）；/minutes 整理会议纪要');
      processed += 1;
      notes.push('start');
      continue;
    }
    if (text === '/reset') {
      if (msgTableId) {
        const filter = encodeURIComponent(JSON.stringify({ type: 'and', filters: [{ columnName: 'session_id', condition: 'eq', value: 'tg-' + OWNER }] }));
        await this.helpers.httpRequest({ method: 'DELETE', url: N8N + '/data-tables/' + msgTableId + '/rows/delete?filter=' + filter, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, timeout: 15000 }).catch(() => {});
      }
      await sendText(chatId, '已清空本会话记忆');
      processed += 1;
      notes.push('reset');
      continue;
    }
    if (text === '/tools') {
      try {
        const tr = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/admin/tools', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { action: 'list' }, timeout: 20000 });
        const list = (tr && tr.tools) || [];
        if (!list.length) {
          await sendText(chatId, '还没有注册自建流程工具。把你在 n8n 里搭好的带 Webhook 的流程注册进来，之后就能在这里说「跑一下 XX」。注册方法见 README「自建流程工具（L2）」。');
        } else {
          const lines = list.map((t) => '• ' + t.name + ' — ' + String(t.description || t.title || '').slice(0, 80) + '（说「跑一下 ' + String(t.title || t.name) + '」）');
          await sendText(chatId, '已注册的自建流程工具（' + list.length + '）：\n' + lines.join('\n'));
        }
      } catch (eT) {
        await sendText(chatId, '工具列表读取失败，稍后再试。');
      }
      processed += 1;
      notes.push('tools');
      continue;
    }
    if (text === '/memory') {
      try {
        const mr = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/internal/memory', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { action: 'list', limit: 6 }, timeout: 30000 });
        const mine = (mr && mr.mine) || [];
        const lobe = (mr && mr.lobe) || [];
        const lines = ['平台记忆 ' + ((mr && mr.counts && mr.counts.mine) || mine.length) + ' 条：'];
        lines.push(mine.length ? mine.map((m) => '• ' + m.text).join('\n') : '（暂无——在对话里聊点稳定偏好，它就会记住）');
        lines.push('');
        lines.push('LobeHub 记忆 ' + ((mr && mr.counts && mr.counts.lobe) || lobe.length) + ' 条：');
        lines.push(lobe.length ? lobe.map((m) => '• ' + String(m.title || '').slice(0, 60)).join('\n') : '（暂无）');
        await sendText(chatId, lines.join(String.fromCharCode(10)));
      } catch (eM) { await sendText(chatId, "记忆读取失败，稍后再试。"); }
      processed += 1;
      notes.push('memory');
      continue;
    }
    if (text === '/todos') {
      try {
        const tr = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/webhook/admin/todos', headers: { Authorization: AUTH }, timeout: 20000 });
        const open = (tr && tr.open) || [];
        await sendText(chatId, open.length ? '开放待办 ' + (tr.open_count || open.length) + ' 项' + (tr.assigned_count ? '（已指派 ' + tr.assigned_count + '）' : '') + '：\n' + open.map((x) => '• #' + x.id + ' ' + x.text + (x.owner_ref ? ' → ' + (x.owner_name || x.owner_ref) : '') + (x.due_date ? '（' + x.due_date + (x.overdue ? ' · 逾期' : '') + '）' : '')).join('\n') : '暂无开放待办。');
      } catch (eT2) { await sendText(chatId, "待办读取失败，稍后再试。"); }
      processed += 1;
      notes.push('todos');
      continue;
    }
    if (text.indexOf('/todo ') === 0) {
      const rest = text.slice(6).trim();
      const mAt = rest.match(/^@?([\w.\-\u4e00-\u9fa5]{1,24})\s+(.+)$/);
      if (!mAt) {
        await sendText(chatId, '用法：/todo @张三 周五前交周报' + String.fromCharCode(10) + '（人名必须是人员目录里已录入且启用的人，/people 查看）');
        processed += 1; notes.push('todo-syntax'); continue;
      }
      const who = mAt[1];
      const what = mAt[2].slice(0, 300);
      const dm = what.match(/(今天|明天|后天|周一|周二|周三|周四|周五|周六|周日|\d{4}-\d{2}-\d{2})/);
      let due = '';
      if (dm) {
        const w = dm[1];
        const base = new Date(Date.now() + 8 * 3600000);
        const ymd = (d) => new Date(d.getTime() + 8 * 3600000).toISOString().slice(0, 10);
        if (w === '今天') due = ymd(base);
        else if (w === '明天') due = ymd(new Date(base.getTime() + 86400000));
        else if (w === '后天') due = ymd(new Date(base.getTime() + 2 * 86400000));
        else if (/^\d{4}-/.test(w)) due = w;
        else {
          const MAP = { '周一': 1, '周二': 2, '周三': 3, '周四': 4, '周五': 5, '周六': 6, '周日': 0 };
          const target = MAP[w];
          let d = base;
          for (let k = 1; k <= 7; k++) { d = new Date(base.getTime() + k * 86400000); if (d.getUTCDay() === target) break; }
          due = ymd(d);
        }
      }
      try {
        const ar = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/admin/todos/add', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { text: what, owner: who, due_date: due || undefined, via: 'tg' }, timeout: 20000 });
        if (ar && ar.error) await sendText(chatId, '派发失败：' + String(ar.error.message || ar.error.code || '未知错误'));
        else await sendText(chatId, '已派给 ' + who + '：' + what + (due ? String.fromCharCode(10) + '截止 ' + due : ''));
      } catch (eAdd) {
        const em = String((eAdd && eAdd.message) || '');
        let shown = false;
        const bi = em.indexOf('{');
        if (bi >= 0) { try { const b = JSON.parse(em.slice(bi)); await sendText(chatId, '派发失败：' + String(b.error.message || b.error.code)); shown = true; } catch (e2) {} }
        if (!shown) await sendText(chatId, '派发失败：人名不在目录里或已停用（/people 查看）。');
      }
      processed += 1; notes.push('todo-assign'); continue;
    }
    if (text === '/docs' || text === '/文档') {
      try {
        const dr = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/admin/docforge', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { action: 'list', limit: 8 }, timeout: 30000 });
        const ds = (dr && dr.docs) || [];
        const NL = String.fromCharCode(10);
        const KL = { minutes: '纪要', weekly: '周报', brief: '晨报', custom: '文档' };
        const base = String($env.CONSOLE_URL || $env.APP_URL || 'http://localhost:3000').replace(/\/$/, '');
        if (!ds.length) {
          await sendText(chatId, '还没有文档。发 /minutes 然后粘贴一段会议记录，我就整理成纪要。');
          processed += 1; notes.push('docs-empty'); continue;
        }
        const L = ['最近文档（' + ds.length + '）：'];
        ds.forEach((d) => L.push('\u2022 [' + (KL[d.kind] || d.kind) + '] ' + String(d.title).slice(0, 30) + NL + '  ' + base + '/api/n8n/docs/' + d.id));
        await sendText(chatId, L.join(NL));
      } catch (eD) { await sendText(chatId, '文档列表读取失败，稍后再试。'); }
      processed += 1; notes.push('docs'); continue;
    }
    if (text.indexOf('/share ') === 0) {
      const rest = text.slice(7).trim().split(/\s+/);
      const sid = Number(rest[0]);
      const to = (rest[1] || '').replace(/^@/, '');
      if (!sid) { await sendText(chatId, '用法：/share 6 或 /share 6 @张伟'); processed += 1; notes.push('share-syntax'); continue; }
      try {
        const sr = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/admin/docforge', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { action: 'share', id: sid, to: to || undefined }, timeout: 45000 });
        if (sr && sr.ok) {
          await sendText(chatId, '已推送「' + String(sr.title).slice(0, 30) + '」给 ' + sr.to + (sr.degraded ? '（对方无通道，已回落给你）' : ''));
        } else await sendText(chatId, '推送失败：' + ((sr && sr.error && sr.error.message) || '未知原因'));
      } catch (eS) { await sendText(chatId, '推送失败，稍后再试。'); }
      processed += 1; notes.push('share'); continue;
    }
    if (text.indexOf('/minutes') === 0) {
      const inline = text.slice(8).trim();
      if (!inline) {
        pendingMinutes[chatId] = Date.now();
        await sendText(chatId, '好，把会议记录原文发给我（不用排版），我整理成纪要并抽出行动项。');
        processed += 1; notes.push('minutes-armed'); continue;
      }
      try {
        const mr = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/admin/docforge', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { action: 'create', kind: 'minutes', text: inline.slice(0, 6000) }, timeout: 120000 });
        if (mr && mr.ok) {
          const base = String($env.CONSOLE_URL || $env.APP_URL || 'http://localhost:3000').replace(/\/$/, '');
          await sendText(chatId, '纪要已生成：' + mr.title + NL + '抽出 ' + (mr.actions || 0) + ' 条行动项' + NL + base + '/api/n8n/docs/' + mr.id);
        } else await sendText(chatId, '纪要生成失败，稍后再试。');
      } catch (eMin) { await sendText(chatId, '纪要生成失败，稍后再试。'); }
      processed += 1; notes.push('minutes'); continue;
    }
    if (text === '/waiting' || text === '/派发') {
      try {
        const dr = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/webhook/admin/delegation', headers: { Authorization: AUTH }, timeout: 25000 });
        const t = (dr && dr.totals) || {};
        const ps = (dr && dr.people) || [];
        const NL = String.fromCharCode(10);
        if (!t.assigned_open) {
          await sendText(chatId, '目前没有派出去的待办。');
          processed += 1; notes.push('waiting-empty'); continue;
        }
        const L = ['我派出去的：开放 ' + t.assigned_open + ' 项 · 逾期 ' + t.overdue + ' · 待回执 ' + t.awaiting_ack + (t.escalated ? ' · 已升级 ' + t.escalated : '')];
        ps.filter((p) => p.open > 0).forEach((p) => {
          L.push('\u2022 ' + p.display_name + '：开放 ' + p.open + (p.overdue ? '（逾期 ' + p.overdue + (p.oldest_overdue_days ? '，最久 ' + p.oldest_overdue_days + ' 天' : '') + '）' : '') + ' · 待回执 ' + p.awaiting_ack + ' · 近7天完成 ' + p.done_7d + (p.has_channel ? '' : ' \u26a0 无通道'));
        });
        const ow = dr && dr.oldest_waiting;
        if (ow) L.push('卡最久：#' + ow.id + ' ' + String(ow.text).slice(0, 24) + '（' + ow.owner + '，逾期 ' + ow.days_late + ' 天）');
        if (t.channel_less) L.push('提示：' + t.channel_less + ' 人没有直达通道，催办会回落给你。');
        await sendText(chatId, L.join(NL));
      } catch (eW) { await sendText(chatId, '派发情况读取失败，稍后再试。'); }
      processed += 1; notes.push('waiting'); continue;
    }
    if (text.indexOf('/done ') === 0) {
      const did = Number(text.slice(6).trim());
      if (!did) { await sendText(chatId, '用法：/done 14（/todos 看编号）'); processed += 1; notes.push('done-syntax'); continue; }
      try {
        const cr = await this.helpers.httpRequest({
          method: 'POST',
          url: 'http://localhost:5678/webhook/admin/todos/complete',
          headers: { Authorization: AUTH, 'Content-Type': 'application/json' },
          body: { id: did },
          timeout: 20000
        });
        if (cr && cr.ok === false) {
          await sendText(chatId, '完成失败：' + String(cr.error || '未知原因'));
        } else {
          const one = (cr && cr.todos && cr.todos[0]) || null;
          await sendText(chatId, '已完成 #' + did + (one ? ' ' + String(one.text || '').slice(0, 40) : ''));
        }
      } catch (eD) {
        await sendText(chatId, '完成失败：' + String((eD && eD.message) || eD).slice(0, 100));
      }
      processed += 1;
      notes.push('done');
      continue;
    }
    if (text.indexOf('/ack ') === 0) {
      const tid = Number(text.slice(5).trim());
      if (!tid) { await sendText(chatId, '用法：/ack 14'); processed += 1; notes.push('ack-syntax'); continue; }
      try {
        const api = (m, p, qs, pl) => this.helpers.httpRequest({ method: m, url: 'http://localhost:5678/api/v1' + p, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: pl, timeout: 15000 });
        const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
        const tid2 = (tables.find((t) => t.name === 'todos') || {}).id;
        if (!tid2) throw new Error('todos table missing');
        const rows = (await api('GET', '/data-tables/' + tid2 + '/rows', { limit: 200 })).data || [];
        const row = rows.find((r) => Number(r.id) === tid);
        if (!row) { await sendText(chatId, '没找到 #' + tid + ' 这条待办。'); processed += 1; notes.push('ack-404'); continue; }
        if (!row.owner_ref) { await sendText(chatId, '#' + tid + ' 是自己的待办，不需要回执（直接完成即可）。'); processed += 1; notes.push('ack-self'); continue; }
        if (row.ack_at) { await sendText(chatId, '#' + tid + ' 已经确认过了。'); processed += 1; notes.push('ack-dup'); continue; }
        await api('PATCH', '/data-tables/' + tid2 + '/rows/update', null, { filter: { type: 'and', filters: [{ columnName: 'id', condition: 'eq', value: tid }] }, data: { ack_at: new Date().toISOString() } });
        await sendText(chatId, '已确认 #' + tid + '（' + row.owner_ref + ' 接了），停止催办。');
      } catch (eA) { await sendText(chatId, '回执写入失败，稍后再试。'); }
      processed += 1; notes.push('ack'); continue;
    }
    if (text === '/mine') {
      try {
        const tr = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/webhook/admin/todos?owner=mine', headers: { Authorization: AUTH }, timeout: 20000 });
        const open = (tr && tr.open) || [];
        await sendText(chatId, open.length ? '我自己的待办 ' + (tr.open_count || open.length) + ' 项：' + String.fromCharCode(10) + open.map((x) => '\u2022 #' + x.id + ' ' + x.text + (x.due_date ? '（' + x.due_date + (x.overdue ? ' \u00b7 逾期' : '') + '）' : '')).join(String.fromCharCode(10)) : '暂无属于自己的待办。');
      } catch (eM2) { await sendText(chatId, '待办读取失败，稍后再试。'); }
      processed += 1; notes.push('mine'); continue;
    }
    if (text === '/people') {
      try {
        const pr = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/webhook/admin/people', headers: { Authorization: AUTH }, timeout: 20000 });
        const ps = (pr && pr.people) || [];
        const RL = { owner: '机主', member: '成员', guest: '外部' };
        const lines = ps.length ? ps.map((p) => '\u2022 ' + (p.display_name || p.name) + '（@' + p.name + '，' + (RL[p.role] || p.role) + '，' + (p.active ? '启用' : '停用') + '）') : ['（暂无）'];
        await sendText(chatId, '人员目录 ' + ps.length + ' 人：' + String.fromCharCode(10) + lines.join(String.fromCharCode(10)));
      } catch (eP) { await sendText(chatId, '人员目录读取失败，稍后再试。'); }
      processed += 1; notes.push('people'); continue;
    }
    if (text === '/reminders') {
      try {
        const tr = await this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/webhook/admin/reminders', headers: { Authorization: AUTH }, timeout: 20000 });
        const p = (tr && tr.pending) || [];
        const rec = (tr && tr.recent) || [];
        const lines = ['待触发 ' + (tr.pending_count || p.length) + ' 条：'];
        lines.push(p.length ? p.map((x) => '• #' + x.id + ' ' + x.text + (x.owner_ref ? ' → ' + (x.owner_name || x.owner_ref) : '') + (x.due_local ? '（' + x.due_local + '）' : '')).join('\n') : '（无）');
        if (rec.length) lines.push('最近：\n' + rec.slice(0, 4).map((x) => '• [' + x.status + '] ' + x.text).join('\n'));
        await sendText(chatId, lines.join(String.fromCharCode(10)));
      } catch (eR) { await sendText(chatId, "提醒读取失败，稍后再试。"); }
      processed += 1;
      notes.push('reminders');
      continue;
    }
    await tg('sendChatAction', { chat_id: chatId, action: 'typing' }).catch(() => {});
    let reply = '';
    let memCtx = '';
    try {
      const mem = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/internal/memory', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { action: 'retrieve', text: text.slice(0, 500) }, timeout: 20000 });
      memCtx = String((mem && mem.context) || '').slice(0, 1800);
      if (memCtx) console.log('[memory] context chars=' + memCtx.length);
    } catch (eMem) {}
    let gwDone = false;
    const gwTimer = (async () => { await sleep(12000); if (!gwDone) await sendText(chatId, '⏳ 还在处理，稍等一下…').catch(() => {}); })().catch(() => {});
    try {
      const g = await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://localhost:5678/webhook/v1/chat/completions',
        headers: { Authorization: AUTH, 'Content-Type': 'application/json', 'x-session-id': 'tg-' + OWNER, 'x-client': 'telegram' },
        body: { model: 'deepseek-v4-flash', messages: [imgDataUri ? { role: 'user', content: [{ type: 'text', text: text.slice(0, 2000) }, { type: 'image_url', image_url: { url: imgDataUri } }] } : { role: 'user', content: text.slice(0, 4000) }], stream: false, ...(memCtx ? { memory_context: memCtx } : {}) },
        timeout: 150000,
      });
      reply = String((g && g.choices && g.choices[0] && g.choices[0].message && g.choices[0].message.content) || '').trim();
      if (!reply) reply = '（这次没有得到内容回复）';
    } catch (e) {
      reply = '处理失败：' + String((e && e.message) || e).slice(0, 300);
    }
    gwDone = true;
    let voiceSent = false;
    if (viaVoice && reply.length <= 900) {
      try {
        await tg('sendChatAction', { chat_id: chatId, action: 'record_voice' }).catch(() => {});
        const vs = await this.helpers.httpRequest({ method: 'POST', url: 'http://stream-bridge:3211/voice/reply', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { chat_id: chatId, text: reply.slice(0, 900) }, timeout: 150000 });
        voiceSent = !!(vs && vs.ok);
        if (voiceSent) { sent += 1; notes.push('voice-reply'); }
      } catch (eVs) {}
    }
    if (!voiceSent) await sendText(chatId, reply);
    try {
      await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/internal/memory', headers: { Authorization: AUTH, 'Content-Type': 'application/json' }, body: { action: 'extract', user_text: text.slice(0, 1500), assistant_text: String(reply).slice(0, 1500) }, timeout: 90000 });
    } catch (eEx) {}
    processed += 1;
    notes.push('msg:' + text.slice(0, 20));
  }
  await saveOffset(offset);
  if (Date.now() - started > 46000) break;
}
await saveOffset(offset);
return [{ json: { ok: true, processed, sent, sendFailed, offset, notes: notes.slice(0, 12) } }];
